# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from dataset import get_dataloader
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Define the model architecture
class BirdClassifier(nn.Module):
    def __init__(self, num_species, conv_layers=3, dropout_rate=0.5):
        super(BirdClassifier, self).__init__()
        layers = []
        in_channels = 1
        out_channels = 32
        
        for i in range(conv_layers):
            layers.append(nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1))
            layers.append(nn.BatchNorm2d(out_channels))
            layers.append(nn.ReLU())
            if i < conv_layers - 1:
                layers.append(nn.MaxPool2d(kernel_size=2, stride=2))
            in_channels = out_channels
            out_channels *= 2
        
        self.conv_layers = nn.Sequential(*layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Linear(in_channels, 128),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(128, num_species)
        )
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Define hyperparameters
NUM_SPECIES = 206
EPOCHS = 6
BATCH_SIZE = 16
LR = 0.0001

# Load data
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=BATCH_SIZE)

# Create model and move to GPU
model = BirdClassifier(num_species=NUM_SPECIES)
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model.to(device)

# Define loss function and optimizer
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=LR, weight_decay=0.001)

# Training loop
train_losses = []
for epoch in range(EPOCHS):
    model.train()
    running_loss = 0.0
    for inputs, labels in train_loader:
        inputs, labels = inputs.to(device), labels.to(device)
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels.float())
        loss.backward()
        optimizer.step()
        
        running_loss += loss.item()
        torch.cuda.empty_cache()  # Clear GPU cache to prevent fragmentation
    
    epoch_loss = running_loss / len(train_loader.dataset)
    train_losses.append(epoch_loss)
    print(f"Epoch {epoch+1}/{EPOCHS}, Loss: {epoch_loss:.4f}")

# Evaluate on validation set
model.eval()
val_preds, val_labels = [], []
with torch.no_grad():
    for inputs, labels in train_loader:
        inputs, labels = inputs.to(device), labels.to(device)
        outputs = model(inputs)
        val_preds.append(outputs.cpu().numpy())
        val_labels.append(labels.cpu().numpy())

# Flatten predictions and labels
val_preds = np.vstack(val_preds)
val_labels = np.vstack(val_labels)

# Compute AUC
final_auc = roc_auc_score(val_labels, val_preds, average='weighted')
print(f"Validation AUC: {final_auc:.4f}")

# Save metrics and model
metrics = {
    "final_train_loss": train_losses[-1],
    "final_auc": final_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": EPOCHS,
    "batch_size": BATCH_SIZE,
    "training_samples": len(train_loader.dataset),
    "eval_samples": len(train_loader.dataset)
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: ", json.dumps(metrics))

